package com.bendemenstudios.steampunksync.client;
import com.bendemenstudios.steampunksync.config.SteampunkSyncConfig;import com.bendemenstudios.steampunksync.model.VersionManifest;import com.bendemenstudios.steampunksync.util.VersionComparator;import com.google.gson.Gson;import net.minecraft.SharedConstants;import net.minecraft.client.Minecraft;import net.neoforged.neoforge.client.event.ClientTickEvent;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.bus.api.SubscribeEvent;import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class UpdateCoordinator{
 private static final Gson GSON=new Gson();private static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();private static boolean started,screenOpened;private UpdateCoordinator(){}public static void register(){NeoForge.EVENT_BUS.register(UpdateCoordinator.class);}
 @SubscribeEvent public static void onClientTick(ClientTickEvent.Post event){if(started||!SteampunkSyncConfig.ENABLE_AUTO_UPDATE.get())return;Minecraft mc=Minecraft.getInstance();if(mc.screen==null)return;started=true;ClientUpdateState.load(mc.gameDirectory.toPath());Thread.startVirtualThread(UpdateCoordinator::checkNow);}
 private static void checkNow(){try{URI uri=URI.create(SteampunkSyncConfig.VERSION_URL.get());if(!"https".equalsIgnoreCase(uri.getScheme()))return;HttpResponse<String> response=HTTP.send(HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(15)).header("Accept","application/json").GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)return;VersionManifest m=GSON.fromJson(response.body(),VersionManifest.class);if(!validManifest(m))return;String installed=ClientUpdateState.installedVersion();if(installed!=null&&VersionComparator.compare(m.version(),installed)<=0)return;ClientUpdateState.setAvailable(m);Minecraft.getInstance().execute(()->{if(!screenOpened&&Minecraft.getInstance().screen!=null){screenOpened=true;Minecraft.getInstance().setScreen(new SteampunkSyncScreen(m));}});}catch(Exception ignored){}}
 private static boolean validManifest(VersionManifest m){if(m==null||blank(m.version())||blank(m.modpack())||blank(m.minecraft())||blank(m.loader())||blank(m.loaderVersion())||blank(m.download())||blank(m.sha256()))return false;if(!SharedConstants.getCurrentVersion().getName().equals(m.minecraft()))return false;if(!"NeoForge".equalsIgnoreCase(m.loader()))return false;if(!m.sha256().trim().matches("(?i)[0-9a-f]{64}"))return false;try{URI u=URI.create(m.download());return "https".equalsIgnoreCase(u.getScheme());}catch(IllegalArgumentException e){return false;}}private static boolean blank(String s){return s==null||s.isBlank();}}
